SELECT ROUND(100.0 * AVG(CASE WHEN c.uuid IN (
    SELECT f.uuid FROM foreign_data AS f WHERE f.language = 'French'
) THEN 1 ELSE 0 END), 2) AS french_translation_pct
FROM cards AS c
WHERE c.power IS NULL OR c.power LIKE '%*%';

SELECT COUNT(*) AS patient_count
FROM (
    SELECT ID FROM Laboratory WHERE SSA NOT IN ('negative', '0')
    INTERSECT
    SELECT ID FROM Laboratory WHERE "U-PRO" NOT IN ('-', '0')
) AS matching_patients;
